good_practice.code:
// New payment methods arrive as new classes; PaymentProcessor never changes.
public interface PaymentMethod {
    void processPayment(double amount);
}

public class CreditCardPayment implements PaymentMethod {
    @Override
    public void processPayment(double amount) {
        // Process credit card payment
    }
}

public class PayPalPayment implements PaymentMethod {
    @Override
    public void processPayment(double amount) {
        // Process PayPal payment
    }
}

public class BitcoinPayment implements PaymentMethod {
    @Override
    public void processPayment(double amount) {
        // Process Bitcoin payment
    }
}

public class PaymentProcessor {
    public void processPayment(PaymentMethod paymentMethod, double amount) {
        paymentMethod.processPayment(amount);
    }
}

bad_practice.code:
public class Bird {
    public void fly() {
        // Flying implementation
    }
}

public class Penguin extends Bird {
    @Override
    public void fly() {
        throw new UnsupportedOperationException("Penguins can't fly");
    }
}

// Breaks as soon as a Penguin is substituted for a Bird
public void makeItFly(Bird bird) {
    bird.fly(); // Throws for Penguin
}

good_practice.code:
// Flying is a capability, not something every Bird has.
public abstract class Bird {
    // Common bird behavior
}

public interface FlyingBird {
    void fly();
}

public class Sparrow extends Bird implements FlyingBird {
    @Override
    public void fly() {
        // Flying implementation
    }
}

public class Penguin extends Bird {
    // Penguin-specific behavior, no fly method
}

bad_practice.code:
public interface Worker {
    void work();
    void eat();
    void sleep();
}

public class Robot implements Worker {
    public void work() {
        // Working implementation
    }

    public void eat() {
        // Robots don't eat, but are forced to implement
        throw new UnsupportedOperationException();
    }

    public void sleep() {
        // Robots don't sleep, but are forced to implement
        throw new UnsupportedOperationException();
    }
}

good_practice.code:
// Each interface is one role; implementers pick the roles they fill.
public interface Workable {
    void work();
}

public interface Eatable {
    void eat();
}

public interface Sleepable {
    void sleep();
}

public class Human implements Workable, Eatable, Sleepable {
    public void work()  { /* Implementation */ }
    public void eat()   { /* Implementation */ }
    public void sleep() { /* Implementation */ }
}

public class Robot implements Workable {
    public void work() { /* Implementation */ }
    // No irrelevant methods to implement
}

